PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000; PRAGMA cache_size=-2048; PRAGMA temp_store=FILE;
 CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY);
 CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, password TEXT NOT NULL, role TEXT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0, totp TEXT NOT NULL DEFAULT '',terminal INTEGER NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL, csrf TEXT NOT NULL, created INTEGER NOT NULL, seen INTEGER NOT NULL);
 CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, time INTEGER NOT NULL, user TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, result TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS sites(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,domains TEXT NOT NULL,kind TEXT NOT NULL,root TEXT NOT NULL,upstream TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,https INTEGER NOT NULL DEFAULT 0,redirect INTEGER NOT NULL DEFAULT 0,not_found TEXT NOT NULL DEFAULT '');
 CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY,name TEXT NOT NULL,schedule TEXT NOT NULL,command TEXT NOT NULL,account TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,timeout INTEGER NOT NULL DEFAULT 300,workdir TEXT NOT NULL DEFAULT '');
 CREATE TABLE IF NOT EXISTS runs(id INTEGER PRIMARY KEY,task_id INTEGER NOT NULL,started INTEGER NOT NULL,finished INTEGER,output TEXT NOT NULL DEFAULT '',status TEXT NOT NULL,exit_code INTEGER);
 CREATE TABLE IF NOT EXISTS metrics(bucket INTEGER NOT NULL,resolution INTEGER NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(bucket,resolution));
 CREATE TABLE IF NOT EXISTS alerts(id INTEGER PRIMARY KEY,key TEXT NOT NULL UNIQUE,message TEXT NOT NULL,active INTEGER NOT NULL,updated INTEGER NOT NULL,ack_by TEXT NOT NULL DEFAULT '',ack_at INTEGER NOT NULL DEFAULT 0);
 INSERT OR IGNORE INTO migrations VALUES(1);
CREATE INDEX IF NOT EXISTS audit_time ON audit(time);
CREATE INDEX IF NOT EXISTS runs_started ON runs(started);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
